    fn LoadPtr_GfxWorld(&mut self, s: &mut Stream, at_stream_start: bool) -> Result<(), LoadError>
    {
        if at_stream_start
        {
            s.load(self.vp_GfxWorld, 4)?;
        }
        s.push_block(0); // XFILE_BLOCK_TEMP
        let zone_ptr_type = s.ptr(self.vp_GfxWorld);
        if zone_ptr_type != 0
        {
            if zone_ptr_type == crate::t6zone::FOLLOWING || zone_ptr_type == crate::t6zone::INSERT
            {
                let p = s.alloc(4);
                s.set_ptr(self.vp_GfxWorld, p);
                let to_insert = if zone_ptr_type == crate::t6zone::INSERT { Some(s.insert_pointer()) } else { None };
                self.v_GfxWorld = p;
                self.Load_GfxWorld(s, true)?;
                s.link_asset("GfxWorld", self.vp_GfxWorld, 1028);
                if let Some(slot) = to_insert { let v = s.ptr(self.vp_GfxWorld); s.set_ptr(slot, v); }
            }
            else
            {
                let p = s.convert_alias(zone_ptr_type)?; s.set_ptr(self.vp_GfxWorld, p);
            }
        }
        s.pop_block();
        Ok(())
    }
